from taf.sbts.oam.coam.admin.interface import admin

from taf.rfrl.procedures.resources.python.admin_info_model.admin_info_model import get_cell_technology
from taf.rfrl.procedures.resources.python.logger import log_input_and_output
from taf.rfrl.procedures.resources.python.test_models.exceptions import CellNotFound, MismatchingValue


@log_input_and_output
def get_nrafcn_variables_for_nr_cell_id(connection, cell_id, sep_channels_for_tdd=False):
    """
    Gets proper carrier nrafcn for provided nr cell id.
    :param connection: AdminConnection object or if used, string name alias
    :type connection: AdminConnection or str
    :param cell_id: global cell id of nr cell
    :type cell_id: int
    :param sep_channels_for_tdd: if True both UL and DL channels will be returned for TDD technology as dictionary,
        default set on False
        e.g. : if sep_channels_for_tdd=False method returns:  {'nrarfcn': 636666}
               if sep_channels_for_tdd=True  method returns:  {'nrarfcn_uplink': 636666, 'nrarfcn_downlink': 636666}
    :type sep_channels_for_tdd: bool
    :return: Dictionary with nrarfcn variables e.g. {'nrarfcn_uplink': 12345, 'nrarfcn_downlink': 67890} for FDD or
                                               e.g. {'nrarfcn': 12345} for TDD
    :rtype: dict
    """
    adm = admin()
    cells_info = adm.get_cells_info(connection=connection, cell_type='nr')
    for cell in cells_info:
        if cell['globalCellId'] == int(cell_id):
            if cell['technology'] == 'TDD':
                if sep_channels_for_tdd:
                    return {'nrarfcn_uplink': int(cell['nrarfcn']),
                            'nrarfcn_downlink': int(cell['nrarfcn'])}
                else:
                    return {'nrarfcn': int(cell['nrarfcn'])}
            elif cell['technology'] == 'FDD':
                return {'nrarfcn_uplink': int(cell['nrarfcnUl']),
                        'nrarfcn_downlink': int(cell['nrarfcnDl'])}
    raise CellNotFound(f"NR cell ID {cell_id} does not exist in current BTS configuration")


@log_input_and_output
def get_earfcn_variables_for_lte_cell_id(connection, cell_id, sep_channels_for_tdd=False):
    """
    Gets proper carrier earfcn for provided lte cell id. In case of LTE IoT guardband or inband cells, earfcn of LTE
    host cell will be returned.
    :param connection: AdminConnection object or if used, string name alias
    :type connection: AdminConnection or str
    :param cell_id: global cell id of lte cell
    :type cell_id: int
    :param sep_channels_for_tdd: if True both UL and DL channels will be returned for TDD technology as dictionary,
        default set on False
        e.g. : if sep_channels_for_tdd=False method returns:  {'earfcn': 18300}
               if sep_channels_for_tdd=True  method returns:  {'earfcn_uplink': 18300, 'earfcn_downlink': 18300}
    :type sep_channels_for_tdd: bool
    :return: Dictionary with earfcn variables e.g. {'earfcn_uplink': 12345, 'earfcn_downlink': 67890} for FDD or
                                              e.g. {'earfcn': 18300} for TDD
    :rtype: dict
    :raises CellNotFound when given cell ID does not exist in current BTS configuration.
    """
    adm = admin()
    cells_info = adm.get_cells_info(connection=connection, cell_type='lte')
    for cell in cells_info:
        if cell['globalCellId'] == int(cell_id):
            if cell['technology'] == 'TDD':
                if sep_channels_for_tdd:
                    return {'earfcn_uplink': int(cell['earfcn']),
                            'earfcn_downlink': int(cell['earfcn'])}
                else:
                    return {'earfcn': int(cell['earfcn'])}
            elif cell['technology'] == 'FDD':
                return {'earfcn_uplink': int(cell['earfcnUplink']),
                        'earfcn_downlink': int(cell['earfcnDownlink'])}
            elif cell['technology'] == 'NB-IoT-FDD':
                if cell['narrowbandIotMode'] == 'standalone':
                    return {'earfcn_uplink': int(cell['standaloneEarfcnUplink']),
                            'earfcn_downlink': int(cell['standaloneEarfcnDownlink'])}
                else:
                    nb_host_cell_id = get_lte_nb_host_cell_id(connection, cell_id)
                    return get_earfcn_variables_for_lte_cell_id(connection, nb_host_cell_id, sep_channels_for_tdd=True)
    raise CellNotFound(f"LTE cell ID {cell_id} does not exist in current BTS configuration")


@log_input_and_output
def get_lte_nb_host_cell_id(connection, iot_cell_id):
    """
    Gets global cell id of LTE host cell for particular IoT guardband or inband cell.
    :param connection: AdminConnection object or if used, string name alias
    :type connection: AdminConnection or str
    :param iot_cell_id: global cell id of lte IoT cell
    :type iot_cell_id: int
    :return: globalCellId of LTE host cell
    :rtype: str
    :raises CellNotFound when given IoT cell ID does not exist in current BTS configuration.
    :raises MismatchingValue when given IoT cell has no host cell.
    """
    adm = admin()
    nb_iot_objects = adm.get_managed_objects(class_name="NBIOT_FDD_M", connection=connection)

    for iot_obj in nb_iot_objects:
        if f"LNCEL_M-{iot_cell_id}" in iot_obj['distName']:
            host_cell_id = iot_obj['parameters']['hostCellId']

            if host_cell_id is None:
                raise MismatchingValue(f"IoT LTE cell with ID {iot_cell_id} doesn't have LTE host cell")
            else:
                return str(host_cell_id)
    raise CellNotFound(f"IoT LTE cell ID {iot_cell_id} doesn't exist in current BTS configuration")


@log_input_and_output
def get_cell_parameters_required_to_setup_test_model(connection, cell_id, cell_type='nr'):
    """
    Gets cell parameters required to setup test model.
    :param connection: AdminConnection object or if used, string name alias
    :type connection: AdminConnection or str
    :param cell_id: global cell id
    :type cell_id: int or str
    :return: cells parameters: "distname_runtime" and "phy_cellid"
    :rtype: dict
    """
    adm = admin()
    cells_info = adm.get_cells_info(connection=connection, cell_type=cell_type)

    for cell in cells_info:
        if cell["globalCellId"] == int(cell_id):
            cell_params = {
                "distname_runtime": cell["id"]["internal"],
                "phy_cellid": cell["physicalCellId"],
                "p_max": cell["maximumOutputPower"]
            }
            return cell_params
    raise CellNotFound("Cell ID {} does not exits in current configuration".format(cell_id))


@log_input_and_output
def get_default_ul_slots_value(connection, cell_id, cell_type='nr'):
    """
    Gets ul_slots value according to cell technology, 4 for TDD technology, 10 for FDD technology.
    :param connection: AdminConnection object or if used, string name alias
    :type connection: AdminConnection or str
    :param cell_id: global cell id
    :type cell_id: int or str
    :param cell_type: cell type, "nr" or "lte", default set on "nr"
    :type cell_type: str
    :return: ul_slots
    :rtype: int
    """
    cell_technology = get_cell_technology(connection=connection, cell_id=int(cell_id), cell_type=cell_type)

    return 4 if cell_technology == "TDD" else 10
